INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف المعايير الرسمية لمسافة شريط البذور في نظام الزراعة الخشنة لتحسين الإنتاجية وتقليل التكاليف. دليل تقني مفصل يعتمد على أفضل الممارسات الزراعية الحديثة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
