INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Learn best practices for growing squash using drip irrigation. This technical guide covers water management and crop optimization for professional farmers.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Comprehensive Guide to Squash Cultivation with Drip Irrigation' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Пешнук: Аҳамияти идоракунии об дар кӯрпаки қабизо</h2><p>Қабизо аз рӯи иқтисодӣ яке аз сабзавотҳои хеле талабчӣ ва гурбонанокст, ки идоракунии дурусти манбаъҳои об метавонад муваффақияти фермаро муайян кунад. Дар шароити баҳори хушк ва нимхушк, истифодаи системаҳои обёркунии фишорӣ чунин <strong>сари чур</strong> ва <strong>обёркунии чуравӣ</strong> на танҳо боиси парҳези баланд аз истифодаи об мегардад, балки бо истеҳсоли рағобати муносиб дар сатҳи хок, рушди якхелаи решаҳо ва камшавии бемориҳои қорчаро дучон аст. Дар ин қисми дастурномаи обёркунӣ, мо принсипҳои аслии пайваст кардани системаҳои обёркунии ба сатҳҳои қабизоро мунтақид намуда мекушем.</p><p>Истифодаи дурусти усулҳои кӯрпакӣ бо обёркунии чуравӣ метавонад парҳези поёниро то 30 фоиз зиёд кунад. Аҳамияти ин масъала он гоҳ зиёдтар мешавад, ки мефаҳмем, решаҳои чуноқи қабизо ниёзманд ба ғизокунии доимӣ ва якхелаҳаст, ки танҳо бо системаҳои дақиқ дастрас аст.</p><h2>Усулҳои кӯрпакӣ ва масофагирии муносиб барои қабизо</h2><h3>Тартиби омодакунии ҷунбонаи нобиш</h3><p>Барои боғи қовуқ бо оварӣ қатрагӣ, шӯравии амиқ ва омехта кардани чорбагиҳо бо хок аз пешниҳодҳое аст, ки бояд пеш аз нобиш иҷро шавад. Замина бояд аз отавҳо тоза карда шавад ва сатҳи он ҳамвор бошад, токи равонашавии об баробар гардад. Дар усулҳои муосири нобиш истифодаи чункаҳои ё гирдаҳои баланд (Ridging) тавсия дода мешавад, зеро ин боиси коҳиши бухоршавии об аз сатҳ ва ҳифси бештари тухтҳо аз ҷиҳати шудагӣ ва бемориҳои заминавӣ мегардад.</p><h3>Фосилаи нобиш ва ҷойгиршавии сатрҳо</h3><p>Фосилаи мувофиқи сатрҳо барои нобиши қовуқ одатан байни ۱۰۰ то ۱۵۰ сантиметр ва фосилаи даруни сатрҳо байни ۴۰ то ۶۰ сантиметр аст. Ин фосилаҳо имконияти гузаштани рӯшноии кофӣ ва ҳаракати ҳаворо фароҳам меорад. Дар системаи нобарқарор, лӯлаи асосӣ дар маркази гирдаҳо ҷойгир карда мешавад ва қатраанконҳо бояд дар паҳлӯи чункаҳои нобиш ҷойгир шаванд, на болои тухтҳо. Барои маълумоти бештар дар бораи таъсири фосилаи нобиш ба хосилорӣ, шумо метавонед ба мақолаи роҳнам кардани зиёдшавии хосилорӣ муроҷиат кунед. Танзими дақиқи фосилаҳо кафолат мекунад, ки ҳар як ноҳия ба як манбаи намнокӣ ва ғизо расонад ва рақобати камтар байни ноҳияҳо ба вуҷуд ояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کدو-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت کدو با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои нобиш ҷиҳодиҳии қатрагӣ расадҳои оварӣ қовуқ</figcaption></figure><h2>Барномагузории оварии қатрагӣ барои қовуқ: ҳисобкунии ва ҳаҷми оварӣ</h2><p>Оварии қатрагӣ барои қовуқ дақиқнокӣ дар фаслҳои гуногуни афзоишро талаб мекунад. Ноҳияи қовуқ ҳассосияти баланд ба фишори об дорад ва решаҳои ҳассоси он аст, ки бо оварии бешумор ва камҳаҷм, саломатии ноҳия кафолат дода мешавад. Дар ин ҷо ҷадвали таҳиякардашудаи идоракунии оварӣ асосан ба марҳилаҳои афзоиш пешниҳод карда мешавад:</p><table><thead><tr><th>Марҳилаи афзоиш</th><th>Шумораи маротибаҳои обкунӣ дар як ҳафта</th><th>Давраи ҳар як обкунӣ (дақиқа)</th><th>Нуқтаҳои муҳим</th></tr></thead><tbody><tr><td>Мунчадан</td><td>2 то 3</td><td>15 то 20</td><td>Об будан лозим аст, аммо оббанд нашуда бошад.</td></tr><tr><td>Рӯйи намоён (тамошавии барг)</td><td>3 то 4</td><td>30 то 45</td><td>Ниёз ба тағзироти маъмулӣ бо орзӣ дорад.</td></tr><tr><td>Гулкушодан ва раҳ (марҳилаи муҳимтарин)</td><td>4 то 5</td><td>45 то 60</td><td>Кам шудани намнокӣ боиси афканидани гургун мегардад; оромӣ бисёр ҳаётӣ аст.</td></tr><tr><td>Устувондан ва пухтагӣ</td><td>2 то 3</td><td>30</td><td>Камешидани тадريجии об барои консентратсия ба пайдоия.</td></tr></tbody></table><p>Истифодаи шлангҳо бо шарафат мувофиқ ва қатраандозҳо бо сарфиёби 4 то 8 литр дар соат беҳтарин интихоб барои сафҳои хурмо аст. Агар шумо аз системаи риштаи тиб истифода баред, боварӣ ҳосил кунед, ки рафҳо тоза боқӣ мондаанд ва об дуруст дар чуқурии рӯгҳо дучор мешавад. Барои фаҳмиши беҳтар чӣ тавр об дар сатҳҳои гуногун тақсим мешавад, омӯзиши дастури беходоришавии ҳосил ва тақсимоти об метавонад фоиданок бошад.</p><h3>Ҷавоб ба савол: Оё риштаи тиб барои хурмо мувофқитар аст ё қатраандозӣ дар сатҳ?</h3><p>Барои хурмо, риштаи тиб зери сатҳ (Sub-surface) аксар вақт интихоби беҳтар ҳисоб мешавад, зеро буғҳо камтар аст ва отлабҳоро дар хатҳо хушк нигоҳ медорад. Аммо қатраандозии сатҳӣ дастрасӣ ва насби арзонтар дорад. Интихоби беҳтар ба буҷет ва шартҳои ҷуғрофӣ вобаста аст. Дар ҳар ду ҳолат, калиди муваффақият дар ихтилоф будан аст. Инчунин, агар отлабҳои зараровар вуҷуд дошта бошанд, обёрӣ риштаи тиб барои шӯб ё сабзиёти шабоҳ метавонад намунаи хуб барои идоракунии рафҳои намӣ дар майдони шумо бошад; бинобар ин омӯзиш <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%81%d9%84%d9%81%d9%84/">дастури риштаи тиб барои шӯб</a> барои принсипҳои умумии ибтидоӣ фоиданок аст.</p><h2>Мӯътобарии амалӣ ва идоракунии ғизоӣ дар паҳлӯи обӣсозии қатраӣ</h2><p>Яке аз муфидтарин арзишҳои обӣсозии қатраӣ барои хурмо (бағъл) имкони расидани муносибҳои ғизоӣ ба атрофи реша аст, ки ба он «ғизогузории бо маҳлул» (Фертигатсия) мегӯянд. Дар ин усул, парҳезҳои кимиёвӣ дар об ҳалшуда, бевосита ба минтақаи ҷабби решаҳо ворид мешаванд ва сарифаи парҳез зиёд мегардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کدو-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت کدو با آبیاری قطره‌ای - تصویر 2"/><figcaption>тарзи шикунии парҳез обӣсозии қатраӣ расули парҳез барои хурмо</figcaption></figure><ul><li><strong>Нисбатҳои парҳезӣ:</strong> Дар ибтидои рушд аз парҳези нитрогенӣ (аммоний) истифода баред, то баргузорӣ зиёд шавад. Дар мавсими гулгашт, миқдори калиро зиёд кунед, то вазн ва сифати хурмо баланд шавад.</li><li><strong>Похмон шурехӣ:</strong> Обҳои дорои шурехии баланд метавонанд ба решаи хурмо зарар расонанд. Агар аз оби чини шур истифода баред, ҳатман аз навоии ти (типа) истифода баред ва бо сабаби партофтани амиқтар, шуроияро дар қабатҳои болоии замин ҷамъ накунед.</li><li><strong>Филтротсия:</strong> Чӯзакашҳо ба инҳор хеле ҳассосанд. Истинод аз филтри Каспер ё диски филтрон дар оғози система барои пешгирии халалпадарории система ва хушкшавии ногаҳони рафҳо чун ягон ҳоҷатоти муҳим аст.</li></ul><p>Инчунин барои муқоисаи усулҳои кишт кардани намудҳои дигари сабзавот ва беҳтар фаҳмонидани идоракунии захираҳо, омӯзиши миқдори борони лӯбиён сафед дар ҳектар метавонад фаҳмиши шумо дар бораи густариши канопии (Canopy Spread) ҷуръатҳои хурдбастарро беҳтар кунад; бинобар ин ба <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d9%84%d9%88%d8%a8%db%8c%d8%a7-%d8%b3%d9%81%db%8c%d8%af-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори борони лӯбиён сафед дар ҳектар</a> диққат диҳед, то монандӣ ва фарқияти масофаи кишт кардани ин сабзавотҳоро бо хурма фаҳмид.</p><h2>Саволҳои такроршаванда (FAQ)</h2><h3>1. Беҳтарин замонии кишт кардани хурма бо обёркунӣ бо чӯзакаш кай аст?</h3><p>Беҳтарин вақти кишт дар минтақаҳои ҳавои муътадил, нимхушк ва хушк аз моҳи мӯргон то каҳромон барои ғалати бодомии бехшавӣ ва аз моҳи қаримон то марҳамон барои ғалати تابистонӣ аст. ҳамеша бояд хавошро гарм ва омода барои решакиш дошт.</p><h3>2. Чистани чӣ нишонаҳо чун нишон медиҳад, ки хурмаи шумо об зиёд мегирад?</h3><p>Заромидашавии баргҳои поёнӣ, занбарҳои заминӣ ва бӯи номатлоб аз хок, аломатҳои ғарқ будан ва фашукӣи реша мебошанд. Дар ин ҳолат бояд фавран системаи навибанди ё қатрагӣ-иро хомӯш карда, ба хок имкон диҳед, ки намӣ-и худро танзим кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کدو-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت کدو با آبیاری قطره‌ای - تصویر 3"/><figcaption>усули кӯрӣ, парвариши абгурон, расми обёрӣ, қаб</figcaption></figure><h3>3. Оё ман метавонам аз чангорҳои кӯрӣ-и пухидашуда бо системаи қатрагӣ истифода барам?</h3><p>Истифодаи чангори кӯрӣ дар қуллаи шинокӣ тавсия карда мешавад, вале паҳн кардани мустақими чангорҳои пухидашуда ба решаҳои эҳтиёткор бо фишори навибандӣ метавонад боиси сӯхтани реша гардад. Беҳтар аст, ки аз чангорҳои фишурдашуда ё маҳлулҳои моеъ бо консентратсияи танзимшуда тавассути системаи обёрӣ истифода баред.</p><h2>Хулоса: Истифодаи обёрии қатрагӣ барои қаб</h2><p>Таъсироти иқтисодӣ ва муҳити зист аз истифодаи услубҳои пешрафтаи шинокӣ ва парвариши қаб бо обёрии қатрагӣ, аз ҷиҳати таҳриф кардани истифодаи об зиёд аст. Шумо бо эҷоди тартибот дар ҷойгир кардани синфҳо, истифодаи системаҳои шафоҳии об ва риояи дақиқи расми вақти обёрӣ, метавонед ҳосили яксита ва сифати баланд дошта бошед. Калити муваффақият диққат ба тафсилотҳо, ба монанди танзими масофаи қатрагӣҳо аз саққои асосӣ, филтрасияи мувоҷиб ва ғизои мунтазами ноҳия мебошад. Ин равиш на танҳо хатарро кам мекунад, балки шуморо барои идоракунии ҳосили оянда бо ҳаҷми зиёд тайёр мегардонад; бинобар ин, санҷиши миқдори ҳосил дар гектар барои маҳсулоти иловагии дигар метавонад нақшаи роҳро барои ташаккули таъсири корӣ дақиқтар кунад.</p>\n<p><strong>Маводи пайваста:</strong> <a href="https://navar-abyari.ir/taloqutti-tuxm-dor-hektar-miqdor/">taloqutti tuxm dor hektar miqdor</a>, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D8%B9%D9%81%D8%B1%DB%8C-%D8%AF%D8%B1-%D9%87%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8ACD8B9D981D8B1DB8C D8AFD8B1 D987D8B1 D987DAA9D8AAD8A7D8B1</a></p>','Комилӣ дастури кӯштани хурма бо обкунии талқӣ','Калкашии кӯрӯт бо роҳҳои муосир, ба монанди навуи тейп ва қатрагӣ, калиди дастрасӣ ба истеҳсоли баланд ва кам кардани истеъмолы об аст. Ин раҳнамо марҳилаҳои калкашӣ, фосилаи мувофиқ ва санҷиши обориро амалӣ шарҳ медиҳад.','publish','closed','closed','komili-dasturi-kushthani-khurma-obkunii-talqii',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
